	@Test
	void crossThreadCancellationInterruptsAnAdmittedAvailabilityCheck(@TempDir File directory) throws Exception {
		var store = new CallbackStore(directory);
		var repository = new SailRepository(store);
		try (var connection = repository.getConnection(); var worker = Executors.newVirtualThreadPerTaskExecutor()) {
			seed(connection);
			var sail = (LmdbStoreConnection) connection.getSailConnection();
			try (var rows = evaluate(sail)) {
				rows.next();
				var entered = new CountDownLatch(1);
				var release = new CountDownLatch(1);
				store.callback = phase -> {
					if (phase == Phase.AVAILABILITY) {
						entered.countDown();
						try {
							assertTrue(release.await(10, TimeUnit.SECONDS));
						} catch (InterruptedException failure) {
							Thread.currentThread().interrupt();
							throw new QueryInterruptedException("Interrupted during availability", failure);
						}
					}
				};
				var reading = worker.submit(rows::hasNext);
				try {
					assertTrue(entered.await(10, TimeUnit.SECONDS));
					assertEquals(1, store.activeReads.get());
					assertTrue(CooperativeCancellation.forward(rows));
				} finally {
					release.countDown();
				}
				assertInstanceOf(QueryInterruptedException.class,
						assertThrows(ExecutionException.class, () -> reading.get(10, TimeUnit.SECONDS)).getCause());
				assertEquals(0, store.activeReads.get());
			}
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void captureFailureReleasesTheReadAndClosesTheResult(@TempDir File directory) {
		var store = new CallbackStore(directory);
		var repository = new SailRepository(store);
		try (var connection = repository.getConnection()) {
			seed(connection);
			var sail = (LmdbStoreConnection) connection.getSailConnection();
			try (var rows = evaluate(sail)) {
				rows.next();
				var expected = new SailException("capture failure");
				AtomicInteger calls = new AtomicInteger();
				store.callback = phase -> {
					if (phase == Phase.VALUE && calls.getAndIncrement() == 0) {
						throw expected;
					}
				};
				boolean failed = false;
				try {
					rows.hasNext();
					rows.next();
				} catch (QueryEvaluationException failure) {
					failed = true;
					assertSame(expected, failure.getCause());
				}
				assertTrue(failed, "The capture failure must surface from the row hand-over");
				assertEquals(0, store.activeReads.get());
				assertFalse(rows.hasNext());
			}
		} finally {
			repository.shutDown();
		}
	}

	private static final int BULK_ROWS = 600;

